local c=require('common');local o=c.options(arg);local every=assert(math.tointeger(tonumber(o.every)),'--every required');local ticks=assert(math.tointeger(tonumber(o.stall_ticks)),'--stall-ticks required');assert(every>0 and ticks>0,'--every and --stall-ticks must be positive');local stalls={};for i,f in ipairs(c.load_json(assert(o.positional[1])).frames)do if i%every==0 then table.insert(stalls,{team_sequence=f.team_sequence,stall_ticks=ticks})end end;c.write_result(o.output,{stalls=stalls,outbound_must_continue=true})
